    {
        using var self = handle.Lease();
        return Native.rk_embedded_surface_pointer_press(self.Raw, x, y, (uint)button, (uint)modifiers) != 0;
    }

    /// <summary>
    /// Releases a pointer button.
    /// </summary>
    /// <param name="x">The x.</param>
    /// <param name="y">The y.</param>
    /// <param name="button">The button.</param>
    /// <param name="modifiers">The modifiers.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool PointerRelease(float x, float y, PointerButton button, Modifiers modifiers)
    {
        using var self = handle.Lease();
        return Native.rk_embedded_surface_pointer_release(self.Raw, x, y, (uint)button, (uint)modifiers) != 0;
    }

    /// <summary>
    /// Tells the surface that the pointer left it.
    /// </summary>
    public void PointerLeave()
    {
        using var self = handle.Lease();
        Native.rk_embedded_surface_pointer_leave(self.Raw);
    }

    /// <summary>
    /// Turns the scroll wheel.
    /// </summary>
    /// <param name="x">The x.</param>
    /// <param name="y">The y.</param>
    /// <param name="stepsX">Wheel steps to the right; negative to the left.</param>
    /// <param name="stepsY">Wheel steps away from the person; negative toward them.</param>
    /// <param name="modifiers">The modifiers.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool Scroll(float x, float y, float stepsX, float stepsY, Modifiers modifiers)
    {
        using var self = handle.Lease();
        return Native.rk_embedded_surface_scroll(self.Raw, x, y, stepsX, stepsY, (uint)modifiers) != 0;
    }

    /// <summary>
    /// Presses a key. Keys that type text arrive through <see cref="EmbeddedSurface.TypeText"/> instead,
    /// unless Control, Alt or Super is held with them.
    /// </summary>
    /// <param name="key">The key.</param>
    /// <param name="modifiers">The modifiers.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool KeyPress(KeyCode key, Modifiers modifiers)
    {
        using var self = handle.Lease();
        return Native.rk_embedded_surface_key_press(self.Raw, (uint)key, (uint)modifiers) != 0;
    }

    /// <summary>
    /// Releases a key.
    /// </summary>
    /// <param name="key">The key.</param>
    /// <param name="modifiers">The modifiers.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool KeyRelease(KeyCode key, Modifiers modifiers)
    {
        using var self = handle.Lease();
        return Native.rk_embedded_surface_key_release(self.Raw, (uint)key, (uint)modifiers) != 0;
    }

    /// <summary>
    /// Types text that keys produced.
    /// </summary>
    /// <param name="text">The text.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool TypeText(string text)
    {
        using var self = handle.Lease();
        Span<byte> textUtf8 = Interop.Utf8(text, stackalloc byte[Interop.StackLimit], nameof(text));
        fixed (byte* textBytes = textUtf8)
        {
            return Native.rk_embedded_surface_type_text(self.Raw, new Str(textBytes, (nuint)textUtf8.Length)) != 0;
        }
    }

    /// <summary>
    /// Shows an input method's text under composition at the caret.
    /// </summary>
    /// <param name="text">The text.</param>
    /// <param name="caretStart">
    /// The UTF-8 byte offset where the composition's caret starts, or <see cref="Sdk.None"/>.
    /// </param>
    /// <param name="caretEnd">The byte offset where it ends, not before caret_start.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool ComposeText(string text, int caretStart, int caretEnd)
    {
        using var self = handle.Lease();
        Span<byte> textUtf8 = Interop.Utf8(text, stackalloc byte[Interop.StackLimit], nameof(text));
        fixed (byte* textBytes = textUtf8)
        {
            return Native.rk_embedded_surface_compose_text(self.Raw, new Str(textBytes, (nuint)textUtf8.Length), (nint)caretStart, (nint)caretEnd) != 0;
        }
    }

    /// <summary>
    /// Inserts the text an input method composed, replacing any composition.
    /// </summary>
    /// <param name="text">The text.</param>
    /// <returns>Whether the surface used it.</returns>
    public bool CommitText(string text)
    {
        using var self = handle.Lease();
        Span<byte> textUtf8 = Interop.Utf8(text, stackalloc byte[Interop.StackLimit], nameof(text));
        fixed (byte* textBytes = textUtf8)
        {
            return Native.rk_embedded_surface_commit_text(self.Raw, new Str(textBytes, (nuint)textUtf8.Length)) != 0;
        }
    }

    /// <summary>
    /// The pointer shape the surface asks for.
    /// </summary>
    public CursorShape Cursor
    {
        get
        {
            using var self = handle.Lease();
            return (CursorShape)Native.rk_embedded_surface_cursor(self.Raw);
        }
    }

    /// <summary>
    /// Where the caret of the focused text field or editor is, for placing an input method's candidates; 0 by
    /// 0 at the origin while no text has focus.
    /// </summary>
    public Rect Caret
    {
        get
        {
            using var self = handle.Lease();
            return Native.rk_embedded_surface_caret(self.Raw).ToPublic();
        }
    }

    /// <summary>
    /// Plays the surface's exit: its view sees <see cref="View.IsLeaving"/> and drops what leaves, whose
    /// transitions play out; then <see cref="EmbeddedSurfaceBuilder.OnLeft"/> runs.
    /// </summary>
    public void Leave()
    {
        using var self = handle.Lease();
        Native.rk_embedded_surface_leave(self.Raw);
    }

    /// <summary>
    /// Brings a leaving surface back: its view declares everything again, and what was leaving turns back
    /// from where it is.
    /// </summary>
    public void Rejoin()
    {
        using var self = handle.Lease();
        Native.rk_embedded_surface_rejoin(self.Raw);
    }

    /// <summary>
    /// Releases the native object now; a disposed or handed-over object refuses further use.
    /// </summary>
    public void Dispose() => handle.Dispose();

    /// <summary>
    /// Whether both hold the same native object.
    /// </summary>
    /// <param name="other">The object to compare with.</param>
    /// <returns>Whether they are the same object.</returns>
    public bool Equals(EmbeddedSurface? other) =>
        other is not null && other.handle.DangerousGetHandle() == handle.DangerousGetHandle();

    /// <inheritdoc/>
    public override bool Equals(object? obj) => Equals(obj as EmbeddedSurface);

    /// <inheritdoc/>
    public override int GetHashCode() => handle.DangerousGetHandle().GetHashCode();
}

/// <summary>
/// <para>
/// The context of a callback reacting to the person or the system.
/// </para>
/// <para>
/// It is lent to a callback and valid only while the callback runs.
/// </para>
/// </summary>

public sealed unsafe class Context
{
    private nint raw;

    internal Context(nint raw) => this.raw = raw;

    private nint Raw =>
        raw != 0 ? raw : throw new InvalidOperationException("rikka: a Context is valid only while its callback runs");

    internal void Expire() => raw = 0;

    /// <summary>
    /// The window the callback belongs to.
    /// </summary>
    public Window Window
    {
        get
        {
            return Window.Adopt(Native.rk_window_ref(Native.rk_context_window(Raw)));
        }
    }

    /// <summary>
    /// Tells the SDK that this callback changed nothing the view shows.
    /// </summary>
    public void SkipView()
    {
        Native.rk_context_skip_view(Raw);
    }

    /// <summary>
    /// Asks something of the window.
    /// </summary>
    /// <param name="request">The request.</param>
    public void Request(WindowRequest request)
    {
        Native.rk_context_request(Raw, (uint)request);
    }

    /// <summary>
    /// Opens another window.
    /// </summary>
    /// <param name="window">It is consumed.</param>
    public void OpenWindow(WindowBuilder window)
    {
        ArgumentNullException.ThrowIfNull(window);
        nint self = Raw;
        nint windowRaw = window.handle.Take();
        Native.rk_context_open_window(self, windowRaw);
    }

    /// <summary>
    /// Runs a callback once after a delay. A timer or task with the same key is replaced; all of them stop
    /// when the window closes.
    /// </summary>
    /// <param name="key">Names the timer.</param>
    /// <param name="milliseconds">The milliseconds.</param>
    /// <param name="callback">
    /// Reacts to an event. The window's view runs again afterwards unless <see cref="Context.SkipView"/> is
    /// called.
    /// </param>
    public void After(string key, uint milliseconds, ActionCallback callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        Span<byte> keyUtf8 = Interop.Utf8(key, stackalloc byte[Interop.StackLimit], nameof(key));
        nint self = Raw;
        nint userdata = Closures.Retain(callback);
        fixed (byte* keyBytes = keyUtf8)
        {
            Native.rk_context_after(self, new Str(keyBytes, (nuint)keyUtf8.Length), milliseconds, &Trampolines.ActionFn0, userdata, &Closures.Destroy);
        }
    }

    /// <summary>
    /// Runs a callback repeatedly. A timer or task with the same key is replaced; all of them stop when the
    /// window closes.
    /// </summary>
    /// <param name="key">Names the timer.</param>
    /// <param name="milliseconds">The period.</param>
    /// <param name="callback">
    /// Reacts to an event. The window's view runs again afterwards unless <see cref="Context.SkipView"/> is
    /// called.
    /// </param>
    public void Every(string key, uint milliseconds, ActionCallback callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        Span<byte> keyUtf8 = Interop.Utf8(key, stackalloc byte[Interop.StackLimit], nameof(key));
        nint self = Raw;
        nint userdata = Closures.Retain(callback);
        fixed (byte* keyBytes = keyUtf8)
        {
            Native.rk_context_every(self, new Str(keyBytes, (nuint)keyUtf8.Length), milliseconds, &Trampolines.ActionFn0, userdata, &Closures.Destroy);
        }
    }

    /// <summary>
    /// Stops the timer or task with a key.
    /// </summary>
    /// <param name="key">The key.</param>
    public void Cancel(string key)
    {
        Span<byte> keyUtf8 = Interop.Utf8(key, stackalloc byte[Interop.StackLimit], nameof(key));
        fixed (byte* keyBytes = keyUtf8)
        {
            Native.rk_context_cancel(Raw, new Str(keyBytes, (nuint)keyUtf8.Length));
        }
    }

    /// <summary>
    /// Runs blocking work on a background thread, then a callback on the application thread. The callback
    /// does not run if the window closed first.
    /// </summary>
    /// <param name="work">Does blocking work on a background thread. It may run on any thread.</param>
    /// <param name="done">
    /// Reacts to an event. The window's view runs again afterwards unless <see cref="Context.SkipView"/> is
    /// called. It may run on any thread.
    /// </param>
    public void RunInBackground(WorkCallback work, ActionCallback done)
    {
        ArgumentNullException.ThrowIfNull(work);
        ArgumentNullException.ThrowIfNull(done);
        nint self = Raw;
        nint userdata = Closures.Retain(work, done);
        Native.rk_context_run_in_background(self, &Trampolines.WorkFn0, &Trampolines.ActionFn1, userdata, &Closures.Destroy);
    }

    /// <summary>
    /// Puts text on the clipboard.
    /// </summary>
    /// <param name="text">The text.</param>
    public void SetClipboardText(string text)
    {
        Span<byte> textUtf8 = Interop.Utf8(text, stackalloc byte[Interop.StackLimit], nameof(text));
        fixed (byte* textBytes = textUtf8)
        {
            Native.rk_context_set_clipboard_text(Raw, new Str(textBytes, (nuint)textUtf8.Length));
        }
    }

    /// <summary>
    /// Reads the clipboard's text without blocking.
    /// </summary>
    /// <param name="callback">Receives text that may be absent.</param>
    public void ReadClipboardText(TextCallback callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        nint self = Raw;
        nint userdata = Closures.Retain(callback);
        Native.rk_context_read_clipboard_text(self, &Trampolines.TextFn0, userdata, &Closures.Destroy);
    }

    /// <summary>
    /// Shows a file chooser over the window without blocking.
    /// </summary>
    /// <param name="chooser">It is consumed.</param>
    /// <param name="callback">Receives the outcome of a file chooser.</param>
    public void ChooseFiles(FileChooser chooser, FilesCallback callback)
    {
        ArgumentNullException.ThrowIfNull(chooser);
        ArgumentNullException.ThrowIfNull(callback);
        nint self = Raw;
        nint chooserRaw = chooser.handle.Take();
        nint userdata = Closures.Retain(callback);
        Native.rk_context_choose_files(self, chooserRaw, &Trampolines.FilesFn0, userdata, &Closures.Destroy);
    }

    /// <summary>
    /// Shows a message over the window with an OK button, without blocking.
    /// </summary>
    /// <param name="title">The title.</param>
    /// <param name="message">The message.</param>
    public void Alert(string title, string message)
    {
        Span<byte> titleUtf8 = Interop.Utf8(title, stackalloc byte[Interop.StackLimit], nameof(title));
        Span<byte> messageUtf8 = Interop.Utf8(message, stackalloc byte[Interop.StackLimit], nameof(message));
        fixed (byte* titleBytes = titleUtf8)
        {
            fixed (byte* messageBytes = messageUtf8)
            {
                Native.rk_context_alert(Raw, new Str(titleBytes, (nuint)titleUtf8.Length), new Str(messageBytes, (nuint)messageUtf8.Length));
            }
        }
    }

    /// <summary>
    /// Asks the person to confirm something over the window, without blocking.
    /// </summary>
    /// <param name="title">The title.</param>
    /// <param name="message">The message.</param>
    /// <param name="acceptLabel">Names the confirming button with a verb, such as Delete.</param>
    /// <param name="callback">Receives whether the person confirmed; dismissing counts as declining.</param>
    public void Confirm(string title, string message, string acceptLabel, BoolCallback callback)
    {
        ArgumentNullException.ThrowIfNull(callback);
        Span<byte> titleUtf8 = Interop.Utf8(title, stackalloc byte[Interop.StackLimit], nameof(title));
        Span<byte> messageUtf8 = Interop.Utf8(message, stackalloc byte[Interop.StackLimit], nameof(message));
        Span<byte> acceptLabelUtf8 = Interop.Utf8(acceptLabel, stackalloc byte[Interop.StackLimit], nameof(acceptLabel));
        nint self = Raw;
        nint userdata = Closures.Retain(callback);
        fixed (byte* titleBytes = titleUtf8)
        {
            fixed (byte* messageBytes = messageUtf8)
            {
                fixed (byte* acceptLabelBytes = acceptLabelUtf8)
                {
                    Native.rk_context_confirm(self, new Str(titleBytes, (nuint)titleUtf8.Length), new Str(messageBytes, (nuint)messageUtf8.Length), new Str(acceptLabelBytes, (nuint)acceptLabelUtf8.Length), &Trampolines.BoolFn0, userdata, &Closures.Destroy);
                }
            }
        }
    }
}

/// <summary>
/// <para>
/// The builder a view callback declares a window's content into.
/// </para>
/// <para>
/// It is lent to a callback and valid only while the callback runs.
/// </para>
/// </summary>

public sealed unsafe class View
{
    private nint raw;
    private ulong serial;

    internal View(nint raw) => this.raw = raw;

    private nint Raw =>
        raw != 0 ? raw : throw new InvalidOperationException("rikka: a View is valid only while its callback runs");

    internal void Expire() => raw = 0;

    internal nint Current(ulong declared)
    {
        nint current = Raw;
        if (declared != serial)
        {
            throw new InvalidOperationException("rikka: modifiers apply only to the element declared last");
        }
        return current;
    }

    private Element Declared() => new(this, ++serial);

    private Element Contain(Action body)
    {
        serial++;
        body();
        Native.rk_end(Raw);
        return Declared();
    }

    /// <summary>
    /// A colour of the theme the view is drawn in. Views run again when the desktop's theme changes.
    /// </summary>
    /// <param name="role">The role.</param>
    public Color PaletteColor(ColorRole role)
    {
        return Native.rk_view_palette_color(Raw, (uint)role).ToPublic();
    }

    /// <summary>
    /// Whether the view is drawn in a dark theme.
    /// </summary>
    public bool IsDark
    {
        get
        {
            return Native.rk_view_is_dark(Raw) != 0;
        }
    }

    /// <summary>
    /// Whether the view's embedded surface is leaving through <see cref="EmbeddedSurface.Leave"/>: declare
    /// only what stays, so the rest plays its exit transitions.
    /// </summary>
    public bool IsLeaving
    {
        get
        {
            return Native.rk_view_is_leaving(Raw) != 0;
        }
    }

    /// <summary>
    /// A column: children stack top to bottom.
    /// </summary>
    /// <param name="body">Declares the children.</param>
    public Element Column(Action body)
    {
        ArgumentNullException.ThrowIfNull(body);
        Native.rk_column_begin(Raw);
        return Contain(body);
    }

    /// <summary>
    /// A row: children line up from the leading edge.
    /// </summary>
    /// <param name="body">Declares the children.</param>
    public Element Row(Action body)
    {
        ArgumentNullException.ThrowIfNull(body);
        Native.rk_row_begin(Raw);
        return Contain(body);
    }

    /// <summary>
    /// A grid of equal columns filled row by row.
    /// </summary>
    /// <param name="columns">At least 1.</param>
    /// <param name="body">Declares the children.</param>
    public Element Grid(uint columns, Action body)
    {
        ArgumentNullException.ThrowIfNull(body);
        Native.rk_grid_begin(Raw, columns);
        return Contain(body);
    }

    /// <summary>
    /// A box: a decorated, pressable frame around its children, which stack top to bottom.
    /// </summary>
    /// <param name="body">Declares the children.</param>
    public Element Box(Action body)
    {
        ArgumentNullException.ThrowIfNull(body);
        Native.rk_box_begin(Raw);
        return Contain(body);
    }

    /// <summary>
    /// A vertically scrolling area. Give it a height, or let it fill or grow.
    /// </summary>
    /// <param name="body">Declares the children.</param>
    public Element Scroll(Action body)
